package com.sentinel.audit.dto.response;

import io.swagger.v3.oas.annotations.media.Schema;
import lombok.*;

import java.time.Instant;

/**
 * Report generated by the Compliance Verification Engine after checking the cryptographic chain.
 */
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
@Schema(description = "Cryptographic integrity audit report proving zero tampering")
public class VerificationReportResponse {

    @Schema(description = "Target entity ID audited", example = "ACC_1001")
    private String entityId;

    @Schema(description = "True if the mathematical chain is 100% intact, false if broken", example = "true")
    private boolean verified;

    @Schema(description = "Verification status code", example = "VERIFIED_INTACT")
    private String status;

    @Schema(description = "Total number of chained records traversed and mathematically verified", example = "15")
    private int totalRecordsChecked;

    @Schema(description = "Sequence number where tampering was detected (null if clean)", example = "null")
    private Long tamperedSequenceNumber;

    @Schema(description = "Expected SHA-256 hash computed dynamically (null if clean)", example = "null")
    private String expectedHash;

    @Schema(description = "Actual hash found stored in the database (null if clean)", example = "null")
    private String storedHash;

    @Schema(description = "Human-readable compliance audit verdict", example = "All 15 blocks verified. Zero tampering detected across entire historical ledger.")
    private String message;

    @Schema(description = "Timestamp when the audit was performed")
    private Instant verifiedAt;
}
